    const coreEngine=new class extends JSHTMLCore{constructor(opts={}){super({...opts,edition:"Premium"});this.loadedCache=new Set();}async loadSequence(urls){const results=[];for(const url of urls){if(!this.isLoaded(url)){const res=url.endsWith(".html")?await this.loadHTML(url):await this.loadScript(url);results.push(res);this.loadedCache.add(url);}}return results;}isLoaded(url){return !!this.loadedCache.has(url)||!!document.querySelector('script[src="'+url+'"]');}}({onStart:()=>{uiContainer.classList.add("jl-loading");uiContainer.querySelector(".jl-status-container").style.display="block";uiContainer.querySelector(".jl-log").textContent="Establishing vector pipeline streams...";},onProgress:(e)=>{uiContainer.querySelector(".jl-log").textContent="Linked: "+e.src.split("/").pop();},onComplete:()=>{uiContainer.classList.remove("jl-loading");uiContainer.querySelector(".jl-log").textContent="Thread execution completed.";setTimeout(()=>{if(!uiContainer.classList.contains("jl-loading")){uiContainer.querySelector(".jl-status-container").style.display="none";}},3000);},onError:()=>{uiContainer.classList.remove("jl-loading");uiContainer.querySelector(".jl-log").textContent="Stream pipeline fatal error.";}});
    
