    function makeDraggable(handle,element){let dragging=false,curX,curY,startLeft,startTop;handle.addEventListener("mousedown",e=>{if(e.target.closest(".jl-viewport-close, .jl-viewport-hide, .jl-viewport-fs, .jl-btn-icon"))return;dragging=true;element._dragging=true;curX=e.clientX;curY=e.clientY;const bounds=element.getBoundingClientRect();startLeft=bounds.left;startTop=bounds.top;const moveHandler=ev=>{if(!dragging)return;element.style.left=(startLeft+(ev.clientX-curX))+"px";element.style.top=(startTop+(ev.clientY-curY))+"px";updateLines();};const upHandler=()=>{dragging=false;element._dragging=false;document.removeEventListener("mousemove",moveHandler);document.removeEventListener("mouseup",upHandler);};document.addEventListener("mousemove",moveHandler);document.addEventListener("mouseup",upHandler);});}
    
    function createIsolatedPanel(source,isHtml=false){const pane=document.createElement("div");pane.className="jl-isolated-viewport";pane.style.top="120px";pane.style.left="120px";pane.innerHTML='<div class="jl-viewport-bar"><span style="display:flex;align-items:center;"><span class="jl-ic-window"></span>'+(isHtml?"HTML VIEWPORT":"ISOLATED PANEL CONTAINER")+'</span><div class="jl-viewport-controls"><div class="jl-ic-fs jl-viewport-fs" style="color: var(--text-muted);"></div><span class="jl-viewport-hide">_</span><span class="jl-viewport-close">×</span></div></div><iframe class="jl-viewport-frame" sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-modals"></iframe>';document.body.appendChild(pane);const taskItem=createTaskbarItem(isHtml?"HTML VIEWPORT":"ISOLATED PANEL",pane);const frame=pane.querySelector(".jl-viewport-frame");if(isHtml)frame.srcdoc=source;else{let url=source;if(!url.match(/^https?:\/\//i))url="https://"+url;if(url.endsWith(".js"))frame.srcdoc='<html><head><script src="'+url+'"><\/script></head><body></body></html>';else frame.src=url;}pane.querySelector(".jl-viewport-close").addEventListener("click",()=>{pane.remove();taskItem.remove();updateLines();});pane.querySelector(".jl-viewport-hide").addEventListener("click",()=>{pane.style.display='none';taskItem.classList.add("hidden-state");updateLines();});pane.querySelector(".jl-viewport-fs").addEventListener("click",e=>{e.stopPropagation();pane.classList.toggle("jl-fs");updateLines();});makeDraggable(pane.querySelector(".jl-viewport-bar"),pane);updateLines();}
