    function renderNetworkList(){networkList.innerHTML="";networkUrls.forEach((item,idx)=>{const div=document.createElement("div");div.className="jl-network-item";div.innerHTML='<div class="jl-network-url">'+item.url+'</div><div class="jl-network-status"><div class="jl-status-dot jl-status-'+(item.status||'checking')+'"></div>'+(item.status==='online'?'<span style="color:#00ff88;">ONLINE</span><span class="jl-network-latency">'+(item.latency||'')+'</span>':item.status==='offline'?'<span style="color:#ff3333;">OFFLINE</span>':'<span style="color:#ffaa00;">CHECKING...</span>')+'<button class="jl-btn-icon jl-network-remove" data-idx="'+idx+'" style="opacity:0.5;margin-left:8px;width:20px;height:20px;">×</button></div>';networkList.appendChild(div);});}
